+    // Fiat-Shamir island co-tuned for the F_CUT=79 op-stream (REROLL=0,
+    // POST_SUB_REROLL=26 validates 0/0/0 over 9024 at 1543q, 1,695,885 Toffoli).
+    set_default_env("DIALOG_REROLL", "0");
+    set_default_env("DIALOG_POST_SUB_REROLL", "26");

+fn cancel_adjacent_toffoli(mut ops: Vec<Op>) -> Vec<Op> {
+    let mut write = 0usize;
+    let mut removed = 0usize;
+    for read in 0..ops.len() {
+        let op = ops[read];
+        if matches!(op.kind, OperationType::CCX | OperationType::CCZ)
+            && write != 0
+            && ops[write - 1] == op
+        {
+            write -= 1;
+            removed += 2;
+        } else {
+            ops[write] = op;
+            write += 1;
+        }
+    }
+    ops.truncate(write);
+    eprintln!("CANCEL_ADJACENT_TOFFOLI removed={removed}");
+    ops
+}
